; Planar line plotter into the WRAM framebuffer (colour 1, plane 0 only).
; Bodies are generated by tools/gbc_genlines.py.

INCLUDE "hw.inc"

SECTION "line", ROM0

; B=x0 C=y0 D=x1 E=y1, all within the viewport (0..127, 0..111). Clobbers all.
DrawLine::
    ld a, d
    cp b
    jr nc, .ordered
    ld a, b
    ld b, d
    ld d, a
    ld a, c
    ld c, e
    ld e, a
.ordered:
    ld a, b
    and 7
    ldh [hPhase], a
    ld a, b
    srl a
    srl a
    srl a
    add FB_HI
    ldh [hPtrH], a
    ld a, c
    add a
    ldh [hPtrL], a
    ld a, d
    sub b
    ld d, a                         ; D = dx
    ld a, e
    sub c                           ; y1 - y0
    jr nc, .down
    cpl
    inc a
    ld e, a                         ; E = dy
    ld a, 1                         ; up
    jr .haveDir
.down:
    ld e, a
    xor a
.haveDir:
    ldh [hKind], a
    ld a, d
    cp e
    jr c, .ymajor
    ld b, d                         ; B = M = dx
    ld c, e                         ; C = m = dy
    ldh a, [hKind]
    jr .haveKind
.ymajor:
    ld b, e                         ; B = M = dy
    ld c, d                         ; C = m = dx
    ldh a, [hKind]
    add 2
.haveKind:
    swap a                          ; kind * 16
    ld e, a
    ldh a, [hPhase]
    add a
    add e
    ld e, a
    ld d, 0
    ld hl, LineTable
    add hl, de
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl                         ; body entry; the `ret` below jumps to it
    ld a, b
    inc a
    ld d, a                         ; D = pixel count
    ldh a, [hPtrH]
    ld h, a
    ldh a, [hPtrL]
    ld l, a
    ld a, b
    srl a                           ; A = M / 2
    ret

INCLUDE "line_bodies.inc"
